local warmup_states=setmetatable({},{__mode='k'})
local function warmup(table_name,action)local value=R.readonly({table=table_name});warmup_states[value]={table=table_name,action=action};return value end
function M.load_source_with_warmup(source,plan,requests,cancellation)
    plan=plan or{};cancellation=cancellation or R.cancellation();if type(requests)~='table'then R.server_error('InvalidPlan')end
    local selection=catalog.select(plan.tables);local selected={};for _,name in ipairs(selection.tables)do selected[name]=true end;local steps={}
    for i,request in ipairs(requests)do local step=warmup_states[request];if not step or not selected[step.table]then R.server_error('InvalidPlan','Warmup outside selection')end;steps[i]=step end
    local snapshot=M.load_source(source,plan,cancellation);for _,step in ipairs(steps)do cancellation.check();step.action(snapshot,cancellation)end;cancellation.check();return snapshot
end
function M.load_with_warmup(root,plan,requests,cancellation)return M.load_source_with_warmup(R.file_source(root),plan,requests,cancellation)end
